using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ConvertGainSomethingOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/ConvertGainSomethingOmenData")]
public class ConvertGainSomethingOmenData : ConvertOmenData
{
	[Header("Convert Gain Something")]
	[SerializeField]
	private bool useDiceConvertedAmount;

	protected override Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance)
	{
		return delegate(List<DiceInstance> diceInstances)
		{
			int count = diceInstances.Count;
			int actionValue = (useDiceConvertedAmount ? (ActionValue * count) : ActionValue);
			OmenLogic.ActivateOmen(BattleAction, actionValue, null, null);
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
	}
}
